export function Ltr({
  lang = "{{lang}}",
  showIcon = {{showIcon}},
  accent = "{{accent}}",
  badgeCount = {{badgeCount}},
}) {
  const labels = { en: "Dashboard", fr: "Tableau de bord", de: "\u00DCbersicht" };
  return (
    <nav dir="ltr" lang={lang} style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "14px 16px", borderRadius: 12, width: 280, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 10 }}>
      {showIcon && <span aria-hidden="true" style={{ width: 30, height: 30, borderRadius: 8, display: "grid", placeItems: "center", flexShrink: 0, background: accent }}>&#9776;</span>}
      <span style={{ flex: 1, fontWeight: 600 }}>{labels[lang]}</span>
      <span style={{ minWidth: 20, height: 20, padding: "0 6px", borderRadius: 999, display: "grid", placeItems: "center", fontSize: 11, fontWeight: 700, color: "#241430", background: accent }}>{badgeCount}</span>
    </nav>
  );
}
